export type AgariDeskPluginPdas = {
  config: typeof findConfigPda;
  deskRef: typeof findDeskRefPda;
  desk: typeof findDeskPda;
  operatorBuyDeskRef: typeof findOperatorBuyDeskRefPda;
};

export type AgariDeskPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function agariDeskProgram() {
  return <T extends AgariDeskPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { agariDesk: AgariDeskPlugin }> => {
    return extendClient(client, {
      agariDesk: <AgariDeskPlugin>{
        accounts: {
          desk: addSelfFetchFunctions(client, getDeskCodec()),
          deskConfig: addSelfFetchFunctions(client, getDeskConfigCodec()),
          deskRef: addSelfFetchFunctions(client, getDeskRefCodec()),
        },
        instructions: {
          adminInitConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAdminInitConfigInstructionAsync(input),
            ),
          adminSetAttestors: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAdminSetAttestorsInstruction(input),
            ),
          adminSetReferenceFeed: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAdminSetReferenceFeedInstructionAsync(input),
            ),
          operatorBuy: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOperatorBuyInstructionAsync(input),
            ),
          operatorCheckpoint: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOperatorCheckpointInstructionAsync(input),
            ),
          operatorSell: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOperatorSellInstructionAsync(input),
            ),
          ownerAllowToken: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOwnerAllowTokenInstructionAsync(input),
            ),
          ownerDeposit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOwnerDepositInstructionAsync(input),
            ),
          ownerDisallowToken: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOwnerDisallowTokenInstructionAsync(input),
            ),
          ownerOpenDesk: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOwnerOpenDeskInstructionAsync(input),
            ),
          ownerRevokeOperator: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOwnerRevokeOperatorInstructionAsync(input),
            ),
          ownerSetLimits: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOwnerSetLimitsInstructionAsync(input),
            ),
          ownerSetMode: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOwnerSetModeInstructionAsync(input),
            ),
          ownerSetOperator: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOwnerSetOperatorInstructionAsync(input),
            ),
          ownerUnpause: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOwnerUnpauseInstructionAsync(input),
            ),
          ownerWithdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOwnerWithdrawInstructionAsync(input),
            ),
          pause: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPauseInstructionAsync(input),
            ),
          publicInitReference: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPublicInitReferenceInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          publicPostReference: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPublicPostReferenceInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
        },
        pdas: {
          config: findConfigPda,
          deskRef: findDeskRefPda,
          desk: findDeskPda,
          operatorBuyDeskRef: findOperatorBuyDeskRefPda,
        },
        identifyAccount: identifyAgariDeskAccount,
        identifyInstruction: identifyAgariDeskInstruction,
        parseInstruction: parseAgariDeskInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
